def stable_unique(items):
    """
    Return a new list containing the elements of `items` with duplicates removed,
    preserving the order of first occurrences. Elements may be integers, strings,
    tuples, lists, or dictionaries. Equality is determined by deep comparison
    of nested structures; dictionary key order is ignored.
    """
    def deep_equal(a, b):
        if type(a) != type(b):
            return False
        if isinstance(a, dict):
            if len(a) != len(b):
                return False
            for k in a:
                if k not in b:
                    return False
                if not deep_equal(a[k], b[k]):
                    return False
            return True
        if isinstance(a, (list, tuple)):
            if len(a) != len(b):
                return False
            for x, y in zip(a, b):
                if not deep_equal(x, y):
                    return False
            return True
        return a == b

    if not items:
        return []

    result = []
    for item in items:
        for seen in result:
            if deep_equal(item, seen):
                break
        else:
            result.append(item)
    return result
