def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []
    freq = {}
    first_index = {}
    original = {}
    for idx, w in enumerate(words):
        key = w.lower()
        if key in freq:
            freq[key] += 1
        else:
            freq[key] = 1
            first_index[key] = idx
            original[key] = w
    items = [(key, freq[key], first_index[key], original[key]) for key in freq]
    items.sort(key=lambda x: (-x[1], x[2]))
    return [(item[3], item[1]) for item in items[:k]]

