import json
import math
from typing import List, Dict, Any

def parse_jsonl_metrics(lines: List[str]) -> Dict[str, Any]:
    invalid = 0
    services: Dict[str, Dict[str, Any]] = {}

    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            invalid += 1
            continue

        # Validate required fields
        service = record.get("service")
        latency_ms = record.get("latency_ms")
        status = record.get("status")

        if (
            not isinstance(service, str)
            or not isinstance(latency_ms, (int, float))
            or not isinstance(status, (int, float))
        ):
            invalid += 1
            continue

        # Initialize service entry if needed
        if service not in services:
            services[service] = {"count": 0, "ok_count": 0, "latencies": []}

        services[service]["count"] += 1
        if 200 <= status < 300:
            services[service]["ok_count"] += 1
        services[service]["latencies"].append(latency_ms)

    # Build result
    result: Dict[str, Any] = {"invalid": invalid}
    for svc in sorted(services.keys()):
        data = services[svc]
        count = data["count"]
        ok_rate = data["ok_count"] / count if count > 0 else 0.0
        if count > 0:
            sorted_latencies = sorted(data["latencies"])
            idx = math.ceil(0.95 * count) - 1
            p95_latency_ms = sorted_latencies[idx]
        else:
            p95_latency_ms = None
        result[svc] = {
            "count": count,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95_latency_ms,
        }

    return result
