import time
import threading
from collections import OrderedDict

class TTLCache:
    def __init__(self, maxsize: int, ttl: float, *, clock=time.time):
        self.maxsize = maxsize
        self.ttl = ttl
        self.clock = clock
        self._lock = threading.RLock()
        self._data = OrderedDict()  # key -> (value, expiry)

    def _is_expired(self, expiry):
        return self.clock() >= expiry

    def get(self, key, default=None):
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return default
            value, expiry = item
            if self._is_expired(expiry):
                del self._data[key]
                return default
            self._data.move_to_end(key)
            return value

    def set(self, key, value):
        with self._lock:
            expiry = self.clock() + self.ttl
            if key in self._data:
                self._data[key] = (value, expiry)
                self._data.move_to_end(key)
            else:
                self._data[key] = (value, expiry)
                # Evict until size <= maxsize
                while len(self._data) > self.maxsize:
                    # Find first non‑expired LRU entry
                    for old_key, (old_val, old_exp) in self._data.items():
                        if not self._is_expired(old_exp):
                            del self._data[old_key]
                            break
                    else:
                        # All entries expired; just pop the oldest
                        self._data.popitem(last=False)

    def delete(self, key):
        with self._lock:
            self._data.pop(key, None)

    def __len__(self):
        with self._lock:
            return len(self._data)
