import threading

class BoundedQueue:
    def __init__(self, capacity):
        self._q = []
        self._cap = capacity
        self._closed = False
        self._lock = threading.Lock()
        self._cond = threading.Condition(self._lock)

    def put(self, item):
        with self._cond:
            if self._closed:
                raise RuntimeError("Queue closed")
            while len(self._q) >= self._cap:
                if self._closed:
                    raise RuntimeError("Queue closed")
                self._cond.wait()
            if self._closed:
                raise RuntimeError("Queue closed")
            self._q.append(item)
            self._cond.notify_all()

    def get(self):
        with self._cond:
            while len(self._q) == 0:
                if self._closed:
                    raise RuntimeError("Queue closed")
                self._cond.wait()
            item = self._q.pop(0)
            self._cond.notify_all()
            return item

    def close(self):
        with self._cond:
            if not self._closed:
                self._closed = True
                self._cond.notify_all()
