import threading
import copy
from typing import Any, Dict, Tuple


class VersionedStore:
    def __init__(self) -> None:
        self._lock = threading.RLock()
        # key -> (value, version)
        self._store: Dict[Any, Tuple[Any, int]] = {}

    def read(self, key: Any) -> Any:
        with self._lock:
            if key not in self._store:
                return None
            value, _ = self._store[key]
            return copy.deepcopy(value)

    def compare_and_set(self, key: Any, expected_version: int, value: Any) -> bool:
        with self._lock:
            if key not in self._store:
                return False
            _, current_version = self._store[key]
            if current_version != expected_version:
                return False
            self._store[key] = (copy.deepcopy(value), current_version + 1)
            return True

    def delete(self, key: Any, expected_version: int) -> bool:
        with self._lock:
            if key not in self._store:
                return False
            _, current_version = self._store[key]
            if current_version != expected_version:
                return False
            del self._store[key]
            return True

    def snapshot(self) -> Dict[Any, Any]:
        with self._lock:
            return {k: copy.deepcopy(v) for k, (v, _) in self._store.items()}
