class ReplicatedLog:
    class Entry:
        __slots__ = ("term", "command")
        def __init__(self, term, command):
            self.term = term
            self.command = command

    def __init__(self):
        self.log = []                # list[Entry]
        self.current_term = 0
        self.commit_index = 0       # 1‑based index of last committed entry
        self.apply_index = 0          # 1‑based index of last applied entry

    # Append a command locally (used by the leader itself)
    def append(self, command):
        self.log.append(self.Entry(self.current_term, command))
        return len(self.log)

    # Receive an AppendEntries RPC from a leader
    # Returns (success: bool, conflict_index: int or None)
    def receive_append(self, term, prev_index, prev_term, entries, leader_commit):
        # Term check
        if term < self.current_term:
            return False, 0
        if term > self.current_term:
            self.current_term = term

        # Prev index / term check
        if prev_index > len(self.log):
            return False, prev_index
        if prev_index == 0:
            if prev_term != 0:
                return False, 0
        else:
            if self.log[prev_index - 1].term != prev_term:
                return False, prev_index

        # Find first conflicting entry
        i = 0
        for i, cmd in enumerate(entries):
            local_idx = prev_index + i
            if local_idx <= len(self.log):
                if self.log[local_idx - 1].term != term:
                    # Conflict: truncate suffix at local_idx-1
                    self.log = self.log[:local_idx - 1]
                    break
            else:
                break

        # Append remaining entries
        for cmd in entries[i:]:
            self.log.append(self.Entry(term, cmd))

        # Update commit index (cannot move backwards)
        new_commit = min(leader_commit, len(self.log))
        if new_commit > self.commit_index:
            self.commit_index = new_commit

        return True, None

    # Commit up to a given index (cannot exceed local log size)
    def commit_to(self, index):
        if index > self.commit_index:
            self.commit_index = min(index, len(self.log))

    # Apply all committed entries that have not yet been applied
    def apply_committed(self):
        if self.commit_index <= self.apply_index:
            return []
        applied = [e.command for e in self.log[self.apply_index:self.commit_index]]
        self.apply_index = self.commit_index
        return applied

    def current_index(self):
        return len(self.log)

    def current_term(self):
        return self.current_term


