import math

def is_multiply_prime(a):
    if not isinstance(a, int) or a <= 1:
        return False
    primes = []
    for i in range(2, int(math.isqrt(a)) + 1):
        if all(i % p != 0 for p in primes):
            primes.append(i)
    count = 0
    temp = a
    for p in primes:
        while temp % p == 0:
            count += 1
            temp //= p
            if count > 3:
                return False
    if temp > 1:
        count += 1
    return count == 3
